var RM=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
// ?s=<step id> opens that step with its failure, fix and rerun, so a PR can link straight to its proof.
var DEEP=parseInt(new URLSearchParams(location.search).get("s"),10)||0;
var S={d:null,code:"",ex:"",st:[],i:0,mode:"walk",tok:0,runPlayed:false,has:{}};

/* helpers */
function el(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
function ic(name,cls){var s=document.createElementNS("http://www.w3.org/2000/svg","svg");s.setAttribute("class","i"+(cls?" "+cls:""));s.setAttribute("aria-hidden","true");var u=document.createElementNS("http://www.w3.org/2000/svg","use");u.setAttribute("href","#i-"+name);s.appendChild(u);return s}
function show(i,on){$(i).classList.toggle("hide",!on)}
function sleep(ms){return new Promise(function(r){ms?setTimeout(r,ms):r()})}
function fmt(s){s=Math.round(+s||0);if(s<60)return s+"s";if(s<3600)return Math.floor(s/60)+"m "+(s%60)+"s";return Math.floor(s/3600)+"h "+Math.floor(s%3600/60)+"m"}
function dur(s){if(s==null)return "";s=+s||0;return s<10?s.toFixed(1)+"s":fmt(s)}
function safeUrl(u){return typeof u==="string"&&/^https?:\/\//i.test(u)}
function host(u){try{return new URL(u).host}catch(e){return u||""}}
function plural(n,w,pl){return n+" "+(n===1?w:(pl||w+"s"))}
