.sn-wm svg{width:26px;height:26px;display:block}
.sn-sep{width:1px;height:22px;background:var(--sn-line);margin:0 6px}
.sn-app,.sn-lk{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 12px 0 6px;border:0;background:none;border-radius:99px;font:500 14px/1 inherit;color:var(--sn-ink);cursor:pointer;white-space:nowrap;transition:background .2s}
