.sn-it b{font-size:14px;font-weight:600}.sn-it small{grid-column:2;font-size:12.5px;color:var(--sn-mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sn-it i{font-style:normal;font-size:12px;font-weight:600;color:var(--sn-mut);grid-row:1/span 2;grid-column:3}
