P = r"D:\Atharva\firstrun\docs\doc-test\index.html"
s = open(P, encoding="utf-8").read()

def rep(old, new, count=1):
    global s
    n = s.count(old)
    if n < 1:
        sys.exit(f"NOT FOUND: {old[:80]!r}")
    s = s.replace(old, new, count if count else n)

def rre(pat, new, flags=re.S):
