# verdict: rewritten
rre(r'function renderVerdict\(d\)\{.*?\n\}\nfunction buildRail', r'''function ghUrl(d){var s=d.docs_source;return s&&s.repo&&s.path?"https://github.com/"+s.repo+"/edit/"+(s.branch||"main")+"/"+s.path:""}
function raisePR(d,cls){
  var u=ghUrl(d),a=el("button","vd-a gh"+(cls?" "+cls:""));a.type="button";a.appendChild(ic("gh"));a.appendChild(document.createTextNode("Raise PR on GitHub"));
  a.title=u?"Copies the PR text, then opens "+d.docs_source.repo+" on GitHub":"Copies the PR text, then opens the docs page";
  a.addEventListener("click",function(){
    if(d.pr_body)copyText(d.pr_body,u?"PR text copied. Edit the file, then paste it as the PR description.":"PR text copied. Use the page's edit link to open the PR.");
    window.open(u||d.source_url,"_blank","noopener");
  });
  return a;
}
function laterRun(d){var g=GROUP[pageKey(d.source_url||d.target)];if(!g)return null;var best=g.best;return best&&best.id!==d.run_id&&best.v!=="open"?best:null}
function renderVerdict(d){
  var V=$("verdict");if(!V||!d)return;V.textContent="";
  var c=counts(d),v=d.verify,ps=Array.isArray(d.patches)?d.patches:[],gu=Array.isArray(d.gave_up)?d.gave_up:[];
  var db=ps.filter(function(p){return p.failure_class==="docs_bug"}),vk=verdictOf(d.status,ps.length);
  var pr=evAll(d).filter(function(e){return e.kind==="pr"&&e.url&&safeUrl(e.url)});
  var head,detail="",tone="ok",acts=el("div","vd-acts");
  if(vk==="fixed"){
    head=db.length?plural(db.length,"docs bug")+" found, fixed and proven.":"The quickstart runs once the container has "+plural(ps.length,"setup fix","setup fixes")+".";
    detail="Step "+(db[0]||ps[0]).step_id+": "+clip((db[0]||ps[0]).reason||(db[0]||ps[0]).old_command,170);
    if(S.ex&&SUM[S.ex])detail=SUM[S.ex];
    if(pr.length)acts.appendChild(ext(pr[0].url,"View the PR on GitHub"+((pr[0].label||"").match(/#\\d+/)?" "+pr[0].label.match(/#\\d+/)[0]:""),"vd-a gh"));
    else if(db.length&&(d.diff||d.pr_body))acts.appendChild(raisePR(d));
    var sf=el("button","vd-a ghost","See the fix");sf.type="button";sf.addEventListener("click",function(){go2("fix")});acts.appendChild(sf);
  }else if(vk==="works"){
    head=c.skip?"Every step FirstRun could run passes as written.":"The quickstart works as written.";
    detail=c.skip?plural(c.skip,"step")+" skipped because "+(c.skip===1?"it needs":"they need")+" a browser, a login or a long-running server.":"";
    if(S.ex&&SUM[S.ex])detail=SUM[S.ex];
  }else{
    tone="mute";var st=d.steps.filter(function(s){return sk(s)==="bad"})[0];
    head=st?"Inconclusive: FirstRun stopped at step "+sid(st,d.steps.indexOf(st))+".":"Inconclusive: the run stopped before any step ran.";
    var er=gu.length?String(gu[0].error||gu[0].reason||"").split(" | ").pop().replace(/\\)\\s*$/,""):"";
    detail="It proved no fix, so this run does not claim the docs are wrong."+(er?" Last output: "+clip(er,150):"");
    var lr=laterRun(d);
    if(lr){var a=el("a","vd-a",lr.v==="fixed"?"Open the later run that proved a fix":"Open the later run that passed");a.href="#ex="+encodeURIComponent(lr.id);acts.appendChild(a)}
    if(st){var sb=el("button","vd-a ghost","See where it stopped");sb.type="button";sb.addEventListener("click",function(){go2("run")});acts.appendChild(sb)}
  }
  var prf=vk==="fixed"&&v?"A fresh container passed "+v.steps_passed+" of "+v.steps_total+" steps.":"";
  var t=el("div","vd-t "+tone);t.appendChild(el("b",null,head));if(prf)t.appendChild(el("span",null," "+prf));V.appendChild(t);
  if(detail)V.appendChild(el("p","vd-d",detail));
  if(acts.childNodes.length)V.appendChild(acts);
}
function buildRail''')

