def test_d6_no_secret_in_tracked_files():
    hits = {}
    for name in _git("ls-files").splitlines():
        path = ROOT / name
        if path.suffix in {".png", ".jpg", ".mp4", ".gif", ".ico"} or not path.is_file():
            continue
