timeout 300 .venv/Scripts/python.exe -c "
import sys,json;sys.path.insert(0,'scripts')
import neatlogs_issues as n
r=n.trace_to_run()
runs={x['id']:x for x in json.load(open('docs/runs/index.json'))['runs']}
tr={t['traceId']:t for t in n.nl('traces','list','--from','2026-10-01T00:00:00Z','--all','--max-items','500','--limit','50')['traces']}
ok=bad=0
for t,rid in r.items():
  a=round(float(tr[t].get('totalCostUsd') or 0),4);b=round(float(runs[rid].get('cost') or 0),4)
  if abs(a-b)<=0.0002: ok+=1
  else: bad+=1; print('mismatch',t[:8],rid,a,b)
print('ok',ok,'bad',bad)" 2>&1 | grep -v "npm warn" | tail -12

